(function(){'use strict';function escapeHtml(s){return String(s).replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c];});}
var STORAGE_KEY='rsc-engagement-v1:'+location.pathname;var STORAGE={load:function(){try{var raw=localStorage.getItem(STORAGE_KEY);if(!raw)return{ran:[],predictionsSeen:[],celebrated:false};var data=JSON.parse(raw);return{ran:Array.isArray(data.ran)?data.ran:[],predictionsSeen:Array.isArray(data.predictionsSeen)?data.predictionsSeen:[],celebrated:Boolean(data.celebrated)};}catch(e){return{ran:[],predictionsSeen:[],celebrated:false};}},save:function(data){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(data));}
catch(e){}}};var PREDICTIONS=(typeof window!=='undefined'&&typeof window.RSC_PREDICTIONS==='object'&&window.RSC_PREDICTIONS)||{};function discoverNextTutorial(){var current=location.pathname.split('/').pop();var links=document.querySelectorAll('#nav a, .col-sm-3 a');var arr=Array.prototype.slice.call(links);for(var i=0;i<arr.length;i++){var href=arr[i].getAttribute('href')||'';if(href===current||href.indexOf(current)>=0){for(var j=i+1;j<arr.length;j++){var next=arr[j].getAttribute('href')||'';if(next&&next.indexOf('.html')!==-1&&next!==current){return{url:next,title:arr[j].textContent.trim()};}}
break;}}
return null;}
function getVisibleBlocks(){var all=Array.prototype.slice.call(document.querySelectorAll('.webr-container'));return all.filter(function(el){return!el.closest('details');});}
function pad2(n){return(n<10?'0':'')+n;}
function buildProgressBar(total){var wrap=document.createElement('div');wrap.className='engagement-progress';wrap.setAttribute('role','progressbar');wrap.setAttribute('aria-valuemin','0');wrap.setAttribute('aria-valuemax',String(total));wrap.setAttribute('aria-valuenow','0');wrap.setAttribute('aria-label','Interactive blocks run on this page');var label=document.createElement('div');label.className='engagement-progress-label';label.innerHTML='<strong><span class="engagement-progress-count">'+pad2(0)+'</span></strong>'+' / '+pad2(total)+' &middot; Interactive Blocks';var pills=document.createElement('div');pills.className='engagement-progress-pills';for(var i=0;i<total;i++){var p=document.createElement('div');p.className='engagement-progress-pill';p.setAttribute('data-index',String(i));pills.appendChild(p);}
wrap.appendChild(label);wrap.appendChild(pills);return wrap;}
function placeProgressBar(bar){var content=document.querySelector('#content')||document.querySelector('.col-sm-7')||document.querySelector('.col-sm-8')||document.body;var meta=content.querySelector('.engagement-header');if(meta&&meta.parentElement===content){meta.after(bar);return;}
var lead=content.querySelector('p.lead');if(lead&&lead.parentElement===content){lead.after(bar);return;}
var h1=content.querySelector('h1');if(h1&&h1.parentElement===content){h1.after(bar);return;}
content.insertBefore(bar,content.firstChild);}
function renderMetaStrip(){var meta=document.querySelector('.engagement-header');if(!meta)return;var difficulty=meta.getAttribute('data-difficulty');var time=meta.getAttribute('data-time');var exercises=meta.getAttribute('data-exercises');var xp=meta.getAttribute('data-xp');var parts=[];if(difficulty){var slug=difficulty.toLowerCase().replace(/[^a-z]/g,'');parts.push('<span class="engagement-meta-diff engagement-meta-diff-'+
escapeHtml(slug)+'">'+escapeHtml(difficulty)+'</span>');}
if(time)parts.push('<span class="engagement-meta-time">~ '+escapeHtml(time)+' min</span>');if(exercises)parts.push('<span class="engagement-meta-count">'+escapeHtml(exercises)+' exercises</span>');if(xp)parts.push('<span class="engagement-meta-xp">'+escapeHtml(xp)+' XP</span>');meta.innerHTML=parts.join('<span class="engagement-meta-dot">&middot;</span>');}
function updateProgressBar(bar,ranIndices,total,flashIndex){var pills=bar.querySelectorAll('.engagement-progress-pill');var countEl=bar.querySelector('.engagement-progress-count');var ranSet={};for(var i=0;i<ranIndices.length;i++)ranSet[ranIndices[i]]=true;for(var j=0;j<pills.length;j++){if(ranSet[j])pills[j].classList.add('is-filled');if(flashIndex===j){pills[j].classList.remove('just-filled');void pills[j].offsetWidth;pills[j].classList.add('just-filled');}}
var ran=ranIndices.length;if(countEl)countEl.textContent=pad2(ran);bar.setAttribute('aria-valuenow',String(ran));if(ran>=total&&total>0){var pillsWrap=bar.querySelector('.engagement-progress-pills');pillsWrap.classList.remove('is-complete');void pillsWrap.offsetWidth;pillsWrap.classList.add('is-complete');}}
function injectPrediction(blockEl,pred){var output=blockEl.querySelector('.webr-output');if(!output)return;if(output.querySelector('.engagement-prediction'))return;var wrap=document.createElement('div');wrap.className='engagement-prediction';wrap.setAttribute('aria-hidden','true');var badge=document.createElement('span');badge.className='engagement-prediction-badge';badge.textContent=pred.type;var content=document.createElement('div');content.className='engagement-prediction-content';if(pred.kind==='svg')content.innerHTML=pred.content;else content.textContent=pred.content;var hint=document.createElement('div');hint.className='engagement-prediction-hint';hint.textContent='Guess, then reveal';wrap.appendChild(badge);wrap.appendChild(content);wrap.appendChild(hint);output.appendChild(wrap);}
function revealPrediction(blockEl){var wrap=blockEl.querySelector('.engagement-prediction');if(!wrap)return;wrap.classList.add('is-revealing');setTimeout(function(){if(wrap.parentNode)wrap.parentNode.removeChild(wrap);},400);}
function buildCompletionCard(total){var card=document.createElement('div');card.className='engagement-completion';card.setAttribute('role','status');card.setAttribute('aria-live','polite');var h1El=document.querySelector('#content h1')||document.querySelector('h1');var h1Text=(h1El&&h1El.textContent?h1El.textContent:'this tutorial').trim();var next=discoverNextTutorial();var ctaHtml=next?'<a class="engagement-completion-cta" href="'+escapeHtml(next.url)+'">'
+'<span>Continue with '+escapeHtml(next.title)+'</span>'
+'<span class="engagement-completion-cta-arrow">\u2192</span></a>':'';card.innerHTML='<button class="engagement-completion-dismiss" type="button" aria-label="Dismiss">\u00d7</button>'+'<p class="engagement-completion-eyebrow">Tutorial Complete</p>'+'<p class="engagement-completion-headline">You finished '+escapeHtml(h1Text)+'</p>'+'<p class="engagement-completion-stat">'+total+' blocks run &middot; Great work</p>'+
ctaHtml;card.querySelector('.engagement-completion-dismiss').addEventListener('click',function(){card.classList.remove('is-visible');setTimeout(function(){if(card.parentNode)card.parentNode.removeChild(card);},450);});return card;}
function init(){var blocks=getVisibleBlocks();var total=blocks.length;if(total===0)return;var state=STORAGE.load();var ranIndices=state.ran.filter(function(i){return i<total;});var ranMap={};ranIndices.forEach(function(i){ranMap[i]=true;});var seenPredictions={};state.predictionsSeen.forEach(function(i){seenPredictions[i]=true;});renderMetaStrip();var bar=buildProgressBar(total);placeProgressBar(bar);updateProgressBar(bar,ranIndices,total);Object.keys(PREDICTIONS).forEach(function(key){var idx=Number(key);if(idx>=total)return;if(ranMap[idx])return;if(seenPredictions[idx])return;injectPrediction(blocks[idx],PREDICTIONS[idx]);});blocks.forEach(function(block,idx){var output=block.querySelector('.webr-output');if(!output)return;var obs=new MutationObserver(function(mutations){for(var i=0;i<mutations.length;i++){var m=mutations[i];if(m.type!=='attributes'||m.attributeName!=='class')continue;var cls=output.className||'';if(cls.indexOf('has-content')!==-1||cls.indexOf('has-error')!==-1||cls.indexOf('has-message')!==-1){markRun(idx);return;}}});obs.observe(output,{attributes:true,attributeFilter:['class']});});document.addEventListener('click',function(e){var btn=e.target&&e.target.closest?e.target.closest('.webr-run-btn'):null;if(!btn)return;var block=btn.closest('.webr-container');if(!block)return;if(!block.querySelector('.engagement-prediction'))return;revealPrediction(block);var blockIdx=blocks.indexOf(block);if(blockIdx>=0&&!seenPredictions[blockIdx]){seenPredictions[blockIdx]=true;persist();}},true);function persist(){var ranList=[];Object.keys(ranMap).forEach(function(k){ranList.push(Number(k));});var seenList=[];Object.keys(seenPredictions).forEach(function(k){seenList.push(Number(k));});STORAGE.save({ran:ranList,predictionsSeen:seenList,celebrated:state.celebrated});}
function markRun(idx){if(ranMap[idx])return;ranMap[idx]=true;var ranList=[];Object.keys(ranMap).forEach(function(k){ranList.push(Number(k));});persist();updateProgressBar(bar,ranList,total,idx);if(ranList.length>=total&&!state.celebrated){state.celebrated=true;persist();showCompletion(total);}}
function showCompletion(total){var card=buildCompletionCard(total);document.body.appendChild(card);requestAnimationFrame(function(){requestAnimationFrame(function(){card.classList.add('is-visible');});});}}
function scheduleInit(){if(window.requestIdleCallback){requestIdleCallback(init,{timeout:2000});}else{setTimeout(init,200);}}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',scheduleInit);}else{scheduleInit();}})();